import crypto from 'crypto'
import { db, sqliteDb } from '@/db/index.js'
import type Database from 'better-sqlite3'
import { customerOrders, customerOrderLineItems, payments, paymentAllocations, sequences, vatRates, bicycles } from '@/db/schema.js'
import { eq, asc, and, sql, sum, count as drizzleCount } from 'drizzle-orm'
import { createCustomerOrderInputSchema } from '@pi-skeleton/shared/validations/customer-order'
import type { CreateCustomerOrderInput, CustomerOrderStatus } from '@pi-skeleton/shared/validations/customer-order'
import { computeLineTotals } from '@shared/lib/pricing.js'

// ============================================================================
// Types
// ============================================================================

/** Result returned after a successful customer order creation */
export interface CustomerOrderResult {
  /** The created order header */
  order: typeof customerOrders.$inferSelect
  /** All line items for this order */
  lineItems: typeof customerOrderLineItems.$inferSelect[]
  /** Payment record (only present when deposit was collected) */
  payment?: typeof payments.$inferSelect
  /** Payment allocation linking deposit to the order (only present when deposit > 0) */
  allocation?: typeof paymentAllocations.$inferSelect
}

/** Full order detail with line items and derived deposit total */
export interface CustomerOrderDetail {
  order: typeof customerOrders.$inferSelect
  lineItems: typeof customerOrderLineItems.$inferSelect[]
  /** Derived from SUM(allocatedAmount) WHERE targetType='customer_order' AND targetId=orderId */
  depositPaid: number
}

/** List result with pagination support */
export interface CustomerOrderListResult {
  orders: typeof customerOrders.$inferSelect[]
  total: number
}

// ============================================================================
// Custom Errors
// ============================================================================

/** Error thrown when deposit is attempted on an order containing leased bicycles */
export class LeasedBicycleDepositError extends Error {
  constructor() {
    super('Deposit collection not allowed for orders containing leased bicycles')
    this.name = 'LeasedBicycleDepositError'
  }
}

// ============================================================================
// Sequence helper — atomic increment for document numbering
// ============================================================================

/**
 * Get the next sequential value for a document number sequence.
 * Atomically increments the counter and returns the new value.
 */
async function getNextSequenceValue(name: string): Promise<number> {
  const updateResult = await db
    .update(sequences)
    .set({ currentValue: sql`${sequences.currentValue} + 1` })
    .where(eq(sequences.name, name))

  if (updateResult.changes === 0) {
    await db.insert(sequences).values({ name, currentValue: 1 })
    return 1
  }

  const [row] = await db
    .select({ currentValue: sequences.currentValue })
    .from(sequences)
    .where(eq(sequences.name, name))

  return row!.currentValue
}

// ============================================================================
// Validation — leased bicycle deposit check
// ============================================================================

/**
 * Check if any bicycle line items in the order reference a leased bicycle.
 * Throws LeasedBicycleDepositError if a lease is found and deposit > 0.
 */
async function validateNoLeasedBicyclesWithDeposit(
  lineItems: CreateCustomerOrderInput['lineItems'],
  depositAmount: number
): Promise<void> {
  if (depositAmount <= 0) return

  // Find all bicycle IDs from bicycle-type line items
  const bicycleIds = lineItems
    .filter(item => item.lineType === 'bicycle' && item.bicycleId)
    .map(item => item.bicycleId!)

  if (bicycleIds.length === 0) return

  // Check if any of these bicycles are leased
  const leasedBikes = await db
    .select({ id: bicycles.id, isLease: bicycles.isLease })
    .from(bicycles)
    .where(sql`${bicycles.id} IN (${sql.join(bicycleIds)}) AND ${bicycles.isLease} = 1`)

  if (leasedBikes.length > 0) {
    throw new LeasedBicycleDepositError()
  }
}

// ============================================================================
// Public API
// ============================================================================

/**
 * Create a customer order atomically in a single database transaction.
 *
 * Flow: validate input → check leased bicycles (if deposit) → get sequence number
 *       → compute line totals → insert order header → insert line items
 *       → optionally create payment + allocation for deposit
 * All-or-nothing: any failure rolls back everything.
 */
export async function createCustomerOrder(rawInput: unknown): Promise<CustomerOrderResult> {
  // Validate input via Zod schema
  const parsed = createCustomerOrderInputSchema.safeParse(rawInput)
  if (!parsed.success) {
    throw new Error(`Invalid order input: ${parsed.error.message}`)
  }

  const input = parsed.data as CreateCustomerOrderInput
  const depositAmount = input.depositAmount ?? 0

  // ---------------------------------------------------------------------------
  // Step 1: Validate leased bicycle constraint (only when deposit > 0)
  // ---------------------------------------------------------------------------
  await validateNoLeasedBicyclesWithDeposit(input.lineItems, depositAmount)

  // ---------------------------------------------------------------------------
  // Step 2: Get order number from sequence table (atomic increment)
  // ---------------------------------------------------------------------------
  const orderNumberSeq = await getNextSequenceValue('customer_order')
  const orderNumber = `CO-${String(orderNumberSeq).padStart(4, '0')}`

  // ---------------------------------------------------------------------------
  // Step 3: Fetch VAT rates needed for line item calculations
  // ---------------------------------------------------------------------------
  const allVatRates = await db.select({ id: vatRates.id, rate: vatRates.rate }).from(vatRates)
  const vatRatesMap = new Map<string, number>()
  for (const row of allVatRates) {
    vatRatesMap.set(row.id, Number(row.rate))
  }

  // ---------------------------------------------------------------------------
  // Step 4: Compute line item totals using shared pricing lib
  // ---------------------------------------------------------------------------
  const lineItemsData = input.lineItems.map((item) => {
    const vatRateBps = vatRatesMap.get(item.vatRateId) ?? 0
    const totals = computeLineTotals(
      item.unitPriceNet,
      item.quantity,
      item.discountPercent ?? null,
      vatRateBps
    )

    return {
      lineType: item.lineType,
      partId: item.partId ?? null,
      laborServiceId: item.laborServiceId ?? null,
      description: item.description,
      quantity: item.quantity,
      unitPriceNet: item.unitPriceNet,
      vatRateId: item.vatRateId,
      discountPercent: item.discountPercent ?? null,
      lineTotalNet: totals.net,
      lineTotalVat: totals.vat,
      lineTotalGross: totals.gross,
      // Bicycle-specific fields
      bicycleId: (item as any).bicycleId ?? null,
      bicycleBrand: (item as any).bicycleBrand ?? null,
      bicycleModel: (item as any).bicycleModel ?? null,
      bicycleYear: (item as any).bicycleYear ?? null,
      bicycleColor: (item as any).bicycleColor ?? null,
      bicycleFrameSize: (item as any).bicycleFrameSize ?? null,
    }
  })

  const totalPriceNet = lineItemsData.reduce((sumVal, item) => sumVal + item.lineTotalNet, 0)

  // ---------------------------------------------------------------------------
  // Step 5: Execute single transaction — all inserts or nothing
  // ---------------------------------------------------------------------------
  const orderId = crypto.randomUUID()
  let paymentId: string | undefined
  let allocationId: string | undefined

  if (depositAmount > 0 && input.paymentMethod) {
    paymentId = crypto.randomUUID()
    allocationId = crypto.randomUUID()
  }

  const client = sqliteDb as Database.Database
  const run = (sqlStr: string, params?: unknown[]) => {
    return client.prepare(sqlStr).run(...(params ?? []))
  }

  try {
    // Begin transaction
    run('BEGIN TRANSACTION')

    const now = Date.now()

    // Insert order header
    run(
      'INSERT INTO customer_orders (id, order_number, customer_id, status, total_price_net, expected_delivery_date, internal_notes, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
      [
        orderId,
        orderNumber,
        input.customerId,
        'pending',
        totalPriceNet,
        input.expectedDeliveryDate ?? null,
        input.internalNotes ?? null,
        now,
      ]
    )

    // Insert line items
    for (const item of lineItemsData) {
      const lineItemId = crypto.randomUUID()
      run(
        'INSERT INTO customer_order_line_items (id, customer_order_id, line_type, part_id, labor_service_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, bicycle_id, bicycle_brand, bicycle_model, bicycle_year, bicycle_color, bicycle_frame_size, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        [
          lineItemId,
          orderId,
          item.lineType,
          item.partId,
          item.laborServiceId,
          item.description,
          item.quantity,
          item.unitPriceNet,
          item.vatRateId,
          item.discountPercent,
          item.lineTotalNet,
          item.lineTotalVat,
          item.lineTotalGross,
          item.bicycleId,
          item.bicycleBrand,
          item.bicycleModel,
          item.bicycleYear,
          item.bicycleColor,
          item.bicycleFrameSize,
          now,
        ]
      )
    }

    // If deposit > 0: create payment + allocation records
    if (depositAmount > 0 && input.paymentMethod) {
      // Insert payment record
      run(
        'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
        [paymentId!, input.paymentMethod, depositAmount, now]
      )

      // Insert payment allocation (payment → customer_order)
      run(
        'INSERT INTO payment_allocations (id, payment_id, target_type, target_id, allocated_amount) VALUES (?, ?, ?, ?, ?)',
        [allocationId!, paymentId!, 'customer_order', orderId, depositAmount]
      )
    }

    // Commit transaction
    run('COMMIT')
  } catch (err) {
    try { run('ROLLBACK') }
    catch {}
    throw err
  }

  // ---------------------------------------------------------------------------
  // Step 6: Fetch and return created entities
  // ---------------------------------------------------------------------------
  const [createdOrder] = await db.select().from(customerOrders).where(eq(customerOrders.id, orderId))
  const lineItemRows = await db.select()
    .from(customerOrderLineItems)
    .where(eq(customerOrderLineItems.orderId, orderId))
    .orderBy(asc(customerOrderLineItems.createdAt))

  let payment: typeof payments.$inferSelect | undefined
  let allocation: typeof paymentAllocations.$inferSelect | undefined

  if (paymentId) {
    const [p] = await db.select().from(payments).where(eq(payments.id, paymentId!))
    payment = p
  }

  if (allocationId) {
    const [a] = await db.select().from(paymentAllocations).where(eq(paymentAllocations.id, allocationId!))
    allocation = a
  }

  return {
    order: createdOrder!,
    lineItems: lineItemRows,
    payment,
    allocation,
  }
}

/**
 * List customer orders with optional status filter.
 */
export async function listCustomerOrders(options?: {
  status?: CustomerOrderStatus
}): Promise<CustomerOrderListResult> {
  // Build where clause with optional status filter
  const whereClause = options?.status ? eq(customerOrders.status, options.status) : undefined

  const orders = await db.select({
    id: customerOrders.id,
    orderNumber: customerOrders.orderNumber,
    customerId: customerOrders.customerId,
    status: customerOrders.status,
    totalPriceNet: customerOrders.totalPriceNet,
    expectedDeliveryDate: customerOrders.expectedDeliveryDate,
    internalNotes: customerOrders.internalNotes,
    createdAt: customerOrders.createdAt,
  })
    .from(customerOrders)
    .where(whereClause)
    .orderBy(asc(customerOrders.createdAt))

  // Get total count for pagination info
  const [{ count: total }] = await db.select({ count: drizzleCount() })
    .from(customerOrders)
    .where(whereClause)

  return { orders, total }
}

/**
 * Find a single customer order by ID with line items and derived deposit total.
 */
export async function findCustomerOrderById(id: string): Promise<CustomerOrderDetail | undefined> {
  const [order] = await db.select().from(customerOrders).where(eq(customerOrders.id, id))
  if (!order) return undefined

  const lineItems = await db.select()
    .from(customerOrderLineItems)
    .where(eq(customerOrderLineItems.orderId, id))
    .orderBy(asc(customerOrderLineItems.createdAt))

  // Derive deposit paid from payment allocations
  const [{ depositPaid }] = await db
    .select({ depositPaid: sql<number>`COALESCE(${sum(paymentAllocations.allocatedAmount)}, 0)` })
    .from(paymentAllocations)
    .where(
      and(
        eq(paymentAllocations.targetType, 'customer_order'),
        eq(paymentAllocations.targetId, id)
      )
    )

  return {
    order,
    lineItems,
    depositPaid: Number(depositPaid),
  }
}

/**
 * Transition a customer order to a new status.
 */
export async function updateCustomerOrderStatus(
  orderId: string,
  newStatus: CustomerOrderStatus
): Promise<typeof customerOrders.$inferSelect> {
  const [updated] = await db
    .update(customerOrders)
    .set({ status: newStatus })
    .where(eq(customerOrders.id, orderId))
    .returning()

  if (!updated) {
    throw new Error(`Customer order not found: ${orderId}`)
  }

  return updated
}

import { Hono } from 'hono'
import {
  createCustomerOrder,
  listCustomerOrders,
  findCustomerOrderById,
  updateCustomerOrderStatus,
  LeasedBicycleDepositError,
} from '../services/customer-order.service.js'

const ordersRoutes = new Hono()

// ============================================================================
// POST /api/orders — Create a customer order with optional deposit
// ============================================================================

interface ErrorResponse {
  error: string
  code?: string
}

ordersRoutes.post('/', async (c) => {
  try {
    const rawInput = await c.req.json()

    const result = await createCustomerOrder(rawInput)

    return c.json(
      {
        order: Object.fromEntries(Object.entries(result.order)),
        lineItems: result.lineItems.map(item => Object.fromEntries(Object.entries(item))),
        payment: result.payment ? Object.fromEntries(Object.entries(result.payment)) : undefined,
        allocation: result.allocation ? Object.fromEntries(Object.entries(result.allocation)) : undefined,
      },
      201
    )
  } catch (err) {
    if (err instanceof LeasedBicycleDepositError) {
      return c.json(
        { error: err.message, code: 'LEASED_BICYCLE_DEPOSIT' } as ErrorResponse,
        409
      )
    }

    if (err instanceof Error && err.message.startsWith('Invalid order input')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' } as ErrorResponse,
        400
      )
    }

    console.error('[POST /api/orders] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /api/orders — List customer orders with optional status filter
// ============================================================================

interface OrdersListResponse {
  orders: Record<string, unknown>[]
  total: number
}

ordersRoutes.get('/', async (c) => {
  const status = c.req.query('status') as 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled' | undefined

  const result = await listCustomerOrders(status ? { status } : undefined)

  return c.json({
    orders: result.orders.map(order => Object.fromEntries(Object.entries(order))),
    total: result.total,
  } as OrdersListResponse)
})

// ============================================================================
// GET /api/orders/:id — Get a single order with full details
// ============================================================================

interface OrderDetailResponse {
  order: Record<string, unknown>
  lineItems: Record<string, unknown>[]
  depositPaid: number
}

ordersRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  const detail = await findCustomerOrderById(id)
  if (!detail) {
    return c.json({ error: 'Order not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json({
    order: Object.fromEntries(Object.entries(detail.order)),
    lineItems: detail.lineItems.map(item => Object.fromEntries(Object.entries(item))),
    depositPaid: detail.depositPaid,
  } as OrderDetailResponse)
})

// ============================================================================
// PATCH /api/orders/:id/status — Transition order status
// ============================================================================

ordersRoutes.patch('/:id/status', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json()
  const newStatus = body.status as 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'

  if (!newStatus || !['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'].includes(newStatus)) {
    return c.json(
      { error: 'Invalid status', code: 'VALIDATION_ERROR' } as ErrorResponse,
      400
    )
  }

  try {
    const updated = await updateCustomerOrderStatus(id, newStatus)

    return c.json({
      order: Object.fromEntries(Object.entries(updated)),
    })
  } catch (err) {
    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    console.error('[PATCH /api/orders/:id/status] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

export default ordersRoutes

