      await updateCustomerOrderStatus(order1.order.id, 'ordered')

      const pendingResult = await listCustomerOrders({ status: 'pending' })
      expect(pendingResult.orders).toHaveLength(1)
      expect(pendingResult.orders[0].status).toBe('pending')

      const orderedResult = await listCustomerOrders({ status: 'ordered' })
      expect(orderedResult.orders).toHaveLength(1)
      expect(orderedResult.orders[0].id).toBe(order1.order.id)
    })
