      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(201)

      const json = await res.json() as Record<string, unknown>
      expect(json.order).toBeDefined()
      expect((json.order as Record<string, unknown>).customerId).toBe('cust-abc-123')
      expect((json.order as Record<string, unknown>).status).toBe('pending')
      expect((json.order as Record<string, unknown>).orderNumber).toMatch(/^CO-\d{4}$/)
      expect((json.order as Record<string, unknown>).totalPriceNet).toBe(2000)

      // No payment when no deposit
      expect(json.payment).toBeUndefined()
      expect(json.allocation).toBeUndefined()

      // Line items created
      const lineItems = json.lineItems as Record<string, unknown>[]
      expect(lineItems).toHaveLength(1)
      expect(lineItems[0].lineType).toBe('part')
    })

    it('should create a customer order with deposit payment', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'part',
            partId: 'p1',
            description: 'Bearing 6205',
            quantity: 1,
            unitPriceNet: 1000,
            vatRateId: 'vat-standard',
          },
