    it('should reject invalid status (400)', async () => {
      const res = await app.request('/api/orders/some-id/status', {
        method: 'PATCH',
        body: JSON.stringify({ status: 'invalid_status' }),
        headers: { 'Content-Type': 'application/json' },
      })

      expect(res.status).toBe(400)
    })
  })
})

/**
 * Orders feature API client.
 */

import type {
  CustomerOrderDetail,
  CustomerOrderListItem,
  CustomerOrderLineItem,
} from './types.js'

// ---------------------------------------------------------------------------
// Types for request/response shapes
// ---------------------------------------------------------------------------

export interface OrdersListResponse {
  orders: CustomerOrderListItem[]
  total: number
}

export interface OrderDetailApiResponse {
  order: CustomerOrderDetail
  lineItems: CustomerOrderLineItem[]
  depositPaid: number
}

interface CreateOrderInput {
  customerId: string | null
  lineItems: Array<{
    lineType: 'part' | 'labor' | 'bicycle'
    partId: string | null
    laborServiceId: string | null
    description: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    discountPercent: number | null
    bicycleId: string | null
    bicycleBrand: string | null
    bicycleModel: string | null
    bicycleYear: number | null
    bicycleColor: string | null
    bicycleFrameSize: string | null
  }>
  depositAmount?: number | null
  paymentMethod?: 'cash' | 'card' | 'bank_transfer' | null
  expectedDeliveryDate?: string | null
}

// ---------------------------------------------------------------------------
// API Functions — Order CRUD
// ---------------------------------------------------------------------------

/** Get paginated order list with optional status filter. */
export async function getOrders(statusFilter?: string): Promise<OrdersListResponse> {
  const params = new URLSearchParams()
  if (statusFilter) params.set('status', statusFilter)

  const response = await fetch(`/api/orders?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch orders list')
  }

  return response.json()
}

/** Get a single order by ID with line items and deposit info. */
export async function getOrder(id: string): Promise<OrderDetailApiResponse> {
  const response = await fetch(`/api/orders/${id}`)

  if (!response.ok) {
    throw new Error('Failed to fetch order')
  }

  return response.json()
}

/** Create a new customer order with optional deposit. */
export async function createOrder(input: CreateOrderInput): Promise<{
  order: CustomerOrderDetail
  lineItems: CustomerOrderLineItem[]
  payment?: Record<string, unknown> | null
  allocation?: Record<string, unknown> | null
}> {
  const response = await fetch('/api/orders', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create order' }))
    throw new Error(error.error || 'Failed to create order')
  }

  return response.json()
}

/** Update the status of a customer order. */
export async function updateOrderStatus(
  id: string,
  status: 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'
): Promise<CustomerOrderDetail> {
  const response = await fetch(`/api/orders/${id}/status`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update order status' }))
    throw new Error(error.error || 'Failed to update order status')
  }

  const json = await response.json()
  return json.order as CustomerOrderDetail
}

/**
 * Orders feature types — mirrors API response shapes for frontend use.
 */

// ============================================================================
// Order Status
// ============================================================================

export type CustomerOrderStatus = 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'

/** Color mapping for status badges */
